/**
 * Blog data access. Content is generated by scripts/gen-blog.py from the
 * WordPress export into src/content/*.json. All reads are static imports so
 * every blog route can be fully prerendered at build time.
 */
import indexData from '@/content/posts-index.json';
import fullData from '@/content/posts-full.json';
import taxData from '@/content/taxonomies.json';

export type Term = { slug: string; name: string };

export type FeaturedImage = {
  src: string;
  alt: string;
  width: number | null;
  height: number | null;
};

export type PostMeta = {
  slug: string;
  title: string;
  date: string;
  modified: string;
  excerpt: string;
  seoTitle: string;
  seoDescription: string;
  category: Term | null;
  categories: Term[];
  tags: Term[];
  featured: FeaturedImage | null;
};

export type PostFull = PostMeta & { html: string };

export type TaxonomyTerm = Term & { count: number };

const index = indexData as PostMeta[];
const full = fullData as Record<string, PostFull>;
const taxonomies = taxData as { categories: TaxonomyTerm[]; tags: TaxonomyTerm[] };

export const PER_PAGE = 24;

/** All posts, newest first. */
export function allPosts(): PostMeta[] {
  return index;
}

export function getPost(slug: string): PostFull | undefined {
  return full[slug];
}

export function allSlugs(): string[] {
  return index.map((p) => p.slug);
}

export function categories(): TaxonomyTerm[] {
  return taxonomies.categories;
}

export function tags(): TaxonomyTerm[] {
  return taxonomies.tags;
}

export function postsByCategory(slug: string): PostMeta[] {
  return index.filter((p) => p.categories.some((c) => c.slug === slug));
}

export function postsByTag(slug: string): PostMeta[] {
  return index.filter((p) => p.tags.some((t) => t.slug === slug));
}

/** Total number of listing pages for a set of posts (24 per page, min 1). */
export function pageCount(total: number): number {
  return Math.max(1, Math.ceil(total / PER_PAGE));
}

/** Slice a post list to one 1-indexed listing page. */
export function page(posts: PostMeta[], n: number): PostMeta[] {
  const start = (n - 1) * PER_PAGE;
  return posts.slice(start, start + PER_PAGE);
}

/** Format an ISO date as the live site does: "F j, Y" → e.g. "July 30, 2026". */
export function formatDate(iso: string): string {
  const d = new Date(iso);
  return d.toLocaleDateString('en-US', {
    month: 'long',
    day: 'numeric',
    year: 'numeric',
    timeZone: 'UTC',
  });
}
